```go
package ingest

import (
	"errors"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"
	"testing"
)

func TestParsePayloadTable(t *testing.T) {
	overCapMetric := strings.Repeat("m", MaxBodyBytes+64)
	cases := []struct {
		name       string
		method     string
		body       string
		wantStatus int
		wantErrIs  error
		wantOut    []string
	}{
		{
			name:       "valid post merges tags and metrics",
			method:     http.MethodPost,
			body:       `{"host":"edge-01","metrics":["cpu.load","mem.rss"]}`,
			wantStatus: http.StatusAccepted,
			wantOut:    []string{"env:prod", "region:eu", "cpu.load", "mem.rss"},
		},
		{
			name:       "rejects non-POST method",
			method:     http.MethodGet,
			body:       `{"host":"edge-01","metrics":["cpu.load"]}`,
			wantStatus: http.StatusMethodNotAllowed,
		},
		{
			name:       "rejects unknown json field",
			method:     http.MethodPost,
			body:       `{"host":"edge-01","metrics":["cpu"],"admin":true}`,
			wantStatus: http.StatusBadRequest,
		},
		{
			name:       "enforces 2048 byte body cap",
			method:     http.MethodPost,
			body:       `{"host":"edge-01","metrics":["` + overCapMetric + `"]}`,
			wantStatus: http.StatusRequestEntityTooLarge,
		},
		{
			name:       "wraps ErrEmptyMetrics on empty slice",
			method:     http.MethodPost,
			body:       `{"host":"edge-01","metrics":[]}`,
			wantStatus: http.StatusUnprocessableEntity,
			wantErrIs:  ErrEmptyMetrics,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// Over-allocate capacity on defaultTags to catch accidental append aliasing.
			backing := make([]string, 2, 8)
			backing[0], backing[1] = "env:prod", "region:eu"
			snapshot := append([]string(nil), backing[:cap(backing)]...)

			req := httptest.NewRequest(tc.method, "/v1/ingest", strings.NewReader(tc.body))
			rec := httptest.NewRecorder()
			got, status, err := ParsePayload(rec, req, backing)

			if status != tc.wantStatus {
				t.Fatalf("status = %d, want %d (err=%v)", status, tc.wantStatus, err)
			}
			if tc.wantErrIs != nil && !errors.Is(err, tc.wantErrIs) {
				t.Fatalf("errors.Is(%v, %v) = false", err, tc.wantErrIs)
			}
			if tc.wantOut != nil {
				if !reflect.DeepEqual(got, tc.wantOut) {
					t.Fatalf("got = %v, want %v", got, tc.wantOut)
				}
				got[0] = "MUTATED"
			}
			if !reflect.DeepEqual(backing[:cap(backing)], snapshot) {
				t.Fatalf("defaultTags backing array mutated: %v", backing[:cap(backing)])
			}
		})
	}
}
