Write a Rust `#[cfg(test)] mod tests` suite for `QuotaValve` verifying `checked_add` overflow returning `None`, `FromStr` malformed input rejections, invalid state machine transitions, and zero-reallocation stack/fixed buffer behavior:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ValveState {
    Idle,
    Active,
    Draining,
    Sealed,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ValveError {
    BadSpec,
    InvalidTransition(ValveState, ValveState),
    NotActive,
}

pub struct QuotaValve {
    limit: u64,
    used: u64,
    state: ValveState,
    recent: [u64; 4],
    cursor: usize,
}

impl FromStr for QuotaValve {
    type Err = ValveError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let (tag, num) = s.split_once(':').ok_or(ValveError::BadSpec)?;
        if tag != "cap" {
            return Err(ValveError::BadSpec);
        }
        let limit: u64 = num.parse().map_err(|_| ValveError::BadSpec)?;
        if limit == 0 {
            return Err(ValveError::BadSpec);
        }
        Ok(Self { limit, used: 0, state: ValveState::Idle, recent: [0; 4], cursor: 0 })
    }
}

impl QuotaValve {
    pub fn transition(&mut self, next: ValveState) -> Result<(), ValveError> {
        let ok = matches!(
            (self.state, next),
            (ValveState::Idle, ValveState::Active)
                | (ValveState::Active, ValveState::Draining)
                | (ValveState::Draining, ValveState::Sealed)
        );
        if !ok {
            return Err(ValveError::InvalidTransition(self.state, next));
        }
        self.state = next;
        Ok(())
    }

    pub fn charge(&mut self, units: u64) -> Result<Option<u64>, ValveError> {
        if self.state != ValveState::Active {
            return Err(ValveError::NotActive);
        }
        let Some(next_used) = self.used.checked_add(units) else {
            return Ok(None);
        };
        if next_used > self.limit {
            return Ok(None);
        }
        self.used = next_used;
        self.recent[self.cursor & 3] = units;
        self.cursor = self.cursor.wrapping_add(1);
        Ok(Some(self.limit - self.used))
    }

    pub fn recent_ptr(&self) -> *const u64 {
        self.recent.as_ptr()
    }
}
```

