import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { GuardedProfileUpdater } from '../src/handlers/updateProfile';

const GOOD_ORIGIN = 'https://app.internal.example';

describe('GuardedProfileUpdater', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-11-22T12:00:00Z'));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('rejects extra privilege fields via strict Zod schema without calling persist', async () => {
    const persist = vi.fn().mockResolvedValue(undefined);
    const updater = new GuardedProfileUpdater(persist);

    const res = await updater.handle('usr_1', GOOD_ORIGIN, {
      displayName: 'Alice',
      isAdmin: true,
      role: 'superuser',
    });

    expect(res).toEqual({ status: 400, error: 'validation_failed' });
    expect(persist).not.toHaveBeenCalled();
  });

  it.each([
    undefined,
    '',
    'null',
    'https://app.internal.example.evil.tld',
    'http://app.internal.example',
  ])('denies untrusted origin %s with 403', async (badOrigin) => {
    const persist = vi.fn().mockResolvedValue(undefined);
    const updater = new GuardedProfileUpdater(persist);

    const res = await updater.handle('usr_1', badOrigin, { displayName: 'Bob' });
    expect(res).toEqual({ status: 403, error: 'origin_denied' });
    expect(persist).not.toHaveBeenCalled();
  });

  it('aborts immediately on pre-aborted AbortSignal without consuming rate-limit quota', async () => {
    const persist = vi.fn().mockResolvedValue(undefined);
    const updater = new GuardedProfileUpdater(persist);
    const ctrl = new AbortController();
    ctrl.abort();

    await expect(
      updater.handle('usr_2', GOOD_ORIGIN, { displayName: 'Cara' }, ctrl.signal),
    ).rejects.toThrow(/Aborted/);
    expect(persist).not.toHaveBeenCalled();
  });

  it('enforces 3 updates per 60s window and resets cleanly at exact boundary', async () => {
    const persist = vi.fn().mockResolvedValue(undefined);
    const updater = new GuardedProfileUpdater(persist);

    for (let i = 0; i < 3; i++) {
      const ok = await updater.handle('usr_3', GOOD_ORIGIN, { displayName: `Name ${i}` });
      expect(ok.status).toBe(200);
    }

    vi.advanceTimersByTime(59_999);
    const blocked = await updater.handle('usr_3', GOOD_ORIGIN, { displayName: 'Blocked' });
    expect(blocked).toEqual({ status: 429, error: 'rate_limited' });

    vi.advanceTimersByTime(1);
    const reopened = await updater.handle('usr_3', GOOD_ORIGIN, { displayName: 'Fresh Window' });
    expect(reopened.status).toBe(200);
    expect(persist).toHaveBeenCalledTimes(4);
  });
});
