Write a Go concurrency stress test (`sync.WaitGroup` + barrier channel, safe for `go test -race`) proving `AccountBook.Transfer` never deadlocks on opposing transfers, never double-spends under contention, and preserves the exact sum of balances:
```go
package ledger

import (
	"errors"
	"sync"
)

var ErrInsufficientFunds = errors.New("insufficient funds")

type account struct {
	mu  sync.Mutex
	bal int64
}

type AccountBook struct {
	accts map[string]*account
}

func NewAccountBook(initial map[string]int64) *AccountBook {
	m := make(map[string]*account, len(initial))
	for k, v := range initial {
		m[k] = &account{bal: v}
	}
	return &AccountBook{accts: m}
}

func (b *AccountBook) Transfer(fromID, toID string, cents int64) error {
	if fromID == toID || cents <= 0 {
		return errors.New("invalid transfer")
	}
	src, dst := b.accts[fromID], b.accts[toID]
	if fromID < toID {
		src.mu.Lock()
		dst.mu.Lock()
	} else {
		dst.mu.Lock()
		src.mu.Lock()
	}
	defer src.mu.Unlock()
	defer dst.mu.Unlock()
	if src.bal < cents {
		return ErrInsufficientFunds
	}
	src.bal -= cents
	dst.bal += cents
	return nil
}

func (b *AccountBook) Balance(id string) int64 {
	a := b.accts[id]
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.bal
}
```

