```python
import hashlib
import json
from typing import Callable

class IdempotencyConflictError(Exception):
    status_code = 409

class PayoutProcessor:
    def __init__(self, charge_fn: Callable[[str, int, str], str]) -> None:
        self._charge_fn = charge_fn
        self._records: dict[str, tuple[str, dict]] = {}

    def submit(self, idem_key: str, dest_acct: str, cents: int, currency: str) -> tuple[int, dict]:
        if not idem_key or len(idem_key) > 128:
            raise ValueError('invalid idempotency key')
        canonical = json.dumps(
            {'dest': dest_acct, 'cents': cents, 'currency': currency.upper()},
            sort_keys=True,
            separators=(',', ':'),
        )
        digest = hashlib.sha256(canonical.encode('utf-8')).hexdigest()
        if idem_key in self._records:
            saved_digest, cached_resp = self._records[idem_key]
            if saved_digest != digest:
                raise IdempotencyConflictError('payload mismatch for idempotency key')
            return 200, dict(cached_resp)
        tx_id = self._charge_fn(dest_acct, cents, currency.upper())
        resp = {'tx_id': tx_id, 'cents': cents, 'currency': currency.upper()}
        self._records[idem_key] = (digest, resp)
        return 201, dict(resp)
