```python
from pathlib import PurePosixPath

MAX_ENTRY_BYTES = 10_485_760

class ManifestEntryError(ValueError):
    pass

def validate_archive_entry(
    member_name: str,
    byte_size: int,
    mtime_sec: int,
    now_sec: int,
    max_age_sec: int = 86_400,
) -> str:
    if not member_name or '\x00' in member_name or len(member_name.encode('utf-8')) > 255:
        raise ManifestEntryError('invalid member name')
    p = PurePosixPath(member_name)
    if p.is_absolute() or '..' in p.parts or member_name.startswith('\\'):
        raise ManifestEntryError('traversal path rejected')
    if isinstance(byte_size, bool) or not (0 <= byte_size <= MAX_ENTRY_BYTES):
        raise ManifestEntryError('entry size out of bounds')
    if mtime_sec > now_sec or (now_sec - mtime_sec) > max_age_sec:
        raise ManifestEntryError('stale or future timestamp')
    return p.as_posix()
