```go
package webhook

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"slices"
)

const MaxAlertBytes = 1024

var ErrDisallowedScope = errors.New("disallowed alert scope")

type AlertReq struct {
	Scope string   `json:"scope"`
	Hosts []string `json:"hosts"`
}

func DecodeAlert(w http.ResponseWriter, r *http.Request, baseHosts []string, allowedScopes []string) ([]string, int, error) {
	if r.Header.Get("Content-Type") != "application/json" {
		return nil, http.StatusUnsupportedMediaType, errors.New("expected application/json")
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxAlertBytes)
	var req AlertReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("alert body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("bad json: %w", err)
	}
	if !slices.Contains(allowedScopes, req.Scope) {
		return nil, http.StatusForbidden, fmt.Errorf("scope %q: %w", req.Scope, ErrDisallowedScope)
	}
	merged := make([]string, 0, len(baseHosts)+len(req.Hosts))
	merged = append(merged, baseHosts...)
	merged = append(merged, req.Hosts...)
	return merged, http.StatusOK, nil
}
