    use super::*;

    #[test]
    fn from_str_enforces_prefix_and_basis_point_bounds() {
        for invalid in ["", "250", "bps=", "bps=0", "bps=10001", "bps=-1", "bps=25.5", "bps=100 "] {
            assert_eq!(invalid.parse::<FeePolicy>().err(), Some(FeeError::ParseError), "raw={invalid}");
        }
        assert!("bps=1".parse::<FeePolicy>().is_ok());
        assert!("bps=10000".parse::<FeePolicy>().is_ok());
