```ts
import { z } from 'zod';

const MintTokenSchema = z.object({
  label: z.string().min(3).max(32),
  ttlSeconds: z.number().int().min(60).max(3600),
}).strict();

const CONSOLE_ORIGINS = new Set(['https://console.vault.internal']);

export class ScopedTokenMinter {
  private windowStart = new Map<string, { used: number; expiresAt: number }>();

  constructor(private signFn: (actor: string, ttl: number, signal?: AbortSignal) => Promise<string>) {}

  async mint(actorId: string, origin: string | null, rawBody: unknown, signal?: AbortSignal) {
    if (!origin || !CONSOLE_ORIGINS.has(origin)) {
      return { status: 403 as const, reason: 'bad_origin' };
    }
    const parsed = MintTokenSchema.safeParse(rawBody);
    if (!parsed.success) {
      return { status: 400 as const, reason: 'schema_rejected' };
    }
    const now = Date.now();
    const entry = this.windowStart.get(actorId);
    if (!entry || now >= entry.expiresAt) {
      this.windowStart.set(actorId, { used: 1, expiresAt: now + 30_000 });
    } else if (entry.used >= 2) {
      return { status: 429 as const, reason: 'mint_throttled' };
    } else {
      entry.used += 1;
    }
    signal?.throwIfAborted();
    const jwt = await this.signFn(actorId, parsed.data.ttlSeconds, signal);
    return { status: 201 as const, token: jwt };
  }
}
