Write a Rust `#[cfg(test)] mod tests` round-trip and malformed-frame rejection suite for the LEB128 varint + XOR-tag packet codec below:
```rust
#[derive(Debug, PartialEq, Eq)]
pub enum WireErr {
    Truncated,
    VarintOverflow,
    TrailingBytes,
    BadChecksum,
}

pub fn encode_packet(seq: u64, body: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(20 + body.len() + 1);
    write_varint(seq, &mut out);
    write_varint(body.len() as u64, &mut out);
    out.extend_from_slice(body);
    let tag = out.iter().fold(0x5A_u8, |acc, &b| acc ^ b.rotate_left(1));
    out.push(tag);
    out
}

fn write_varint(mut n: u64, out: &mut Vec<u8>) {
    while n >= 0x80 {
        out.push((n as u8) | 0x80);
        n >>= 7;
    }
    out.push(n as u8);
}

fn read_varint(buf: &[u8]) -> Result<(u64, usize), WireErr> {
    let mut val = 0_u64;
    for (i, &b) in buf.iter().take(10).enumerate() {
        if i == 9 && b > 1 {
            return Err(WireErr::VarintOverflow);
        }
        val |= ((b & 0x7F) as u64) << (i * 7);
        if b & 0x80 == 0 {
            return Ok((val, i + 1));
        }
    }
    if buf.len() >= 10 { Err(WireErr::VarintOverflow) } else { Err(WireErr::Truncated) }
}

pub fn decode_packet(raw: &[u8]) -> Result<(u64, Vec<u8>), WireErr> {
    if raw.len() < 3 {
        return Err(WireErr::Truncated);
    }
    let (content, &got_tag) = raw.split_last().ok_or(WireErr::Truncated)?;
    let (seq, n1) = read_varint(content)?;
    let (len_u64, n2) = read_varint(&content[n1..])?;
    let len = usize::try_from(len_u64).map_err(|_| WireErr::VarintOverflow)?;
    let rest = &content[n1 + n2..];
    if rest.len() < len {
        return Err(WireErr::Truncated);
    }
    if rest.len() > len {
        return Err(WireErr::TrailingBytes);
    }
    let exp_tag = content.iter().fold(0x5A_u8, |acc, &b| acc ^ b.rotate_left(1));
    if exp_tag != got_tag {
        return Err(WireErr::BadChecksum);
    }
    Ok((seq, rest.to_vec()))
}
