Write a Go test suite for `refunds/dedup.go` verifying first-call gateway execution, cached result replay on duplicate `Idempotency-Key` retries across goroutines, and `409 Conflict` (`ErrPayloadConflict`) when a retry mutates parameters:
```go
package refunds

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"net/http"
	"sync"
)

var ErrPayloadConflict = errors.New("idempotency key reused with mutated payload")

type entry struct {
	hash     [32]byte
	refundID string
}

type RefundCoordinator struct {
	mu    sync.Mutex
	store map[string]entry
	exec  func(chargeID string, cents int64) (string, error)
}

func NewRefundCoordinator(exec func(string, int64) (string, error)) *RefundCoordinator {
	return &RefundCoordinator{store: make(map[string]entry), exec: exec}
}

func (c *RefundCoordinator) Issue(idemKey, chargeID string, cents int64) (int, string, error) {
	digest := sha256.Sum256([]byte(fmt.Sprintf("%s|%d", chargeID, cents)))
	c.mu.Lock()
	defer c.mu.Unlock()
	if prev, ok := c.store[idemKey]; ok {
		if prev.hash != digest {
			return http.StatusConflict, "", ErrPayloadConflict
		}
		return http.StatusOK, prev.refundID, nil
	}
	rfID, err := c.exec(chargeID, cents)
	if err != nil {
		return http.StatusBadGateway, "", err
	}
	c.store[idemKey] = entry{hash: digest, refundID: rfID}
	return http.StatusCreated, rfID, nil
}
