func TestRefundCoordinatorReplayAndConflict(t *testing.T) {
	var gatewayCalls atomic.Int32
	coord := NewRefundCoordinator(func(chargeID string, cents int64) (string, error) {
		n := gatewayCalls.Add(1)
		return "rf_000" + string(rune('0'+n)), nil
	})

	code, id1, err := coord.Issue("ik-ref-1", "ch_900", 4500)
	if err != nil || code != http.StatusCreated || id1 != "rf_0001" {
		t.Fatalf("got (%d, %q, %v), want (201, rf_0001, nil)", code, id1, err)
	}

	// 16 concurrent duplicate retries must all get 200 + rf_0001 without calling exec again
	var wg sync.WaitGroup
	for i := 0; i < 16; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c, id, e := coord.Issue("ik-ref-1", "ch_900", 4500)
			if e != nil || c != http.StatusOK || id != id1 {
				t.Errorf("replay got (%d, %q, %v)", c, id, e)
			}
		}()
	}
	wg.Wait()
	if gatewayCalls.Load() != 1 {
		t.Fatalf("gatewayCalls = %d, want 1", gatewayCalls.Load())
	}

	// Mutating cents or chargeID on the same key must fail closed with 409 Conflict
	mutations := []struct {
		charge string
		cents  int64
	}{
		{"ch_900", 4501},
		{"ch_other", 4500},
	}
	for _, m := range mutations {
		c, id, e := coord.Issue("ik-ref-1", m.charge, m.cents)
		if c != http.StatusConflict || id != "" || !errors.Is(e, ErrPayloadConflict) {
			t.Fatalf("mutation (%v) got (%d, %q, %v), want 409 ErrPayloadConflict", m, c, id, e)
		}
	}
	if gatewayCalls.Load() != 1 {
		t.Fatalf("conflict triggered gateway execution: %d", gatewayCalls.Load())
	}
}

func TestTransientGatewayFailureDoesNotPoisonIdempotencyKey(t *testing.T) {
	failNext := true
	coord := NewRefundCoordinator(func(_ string, _ int64) (string, error) {
		if failNext {
			failNext = false
			return "", errors.New("upstream 502")
		}
		return "rf_recovered", nil
	})
	c1, _, err1 := coord.Issue("ik-retry", "ch_1", 500)
	if c1 != http.StatusBadGateway || err1 == nil {
		t.Fatalf("expected 502 error, got %d %v", c1, err1)
	}
	c2, id2, err2 := coord.Issue("ik-retry", "ch_1", 500)
	if c2 != http.StatusCreated || id2 != "rf_recovered" || err2 != nil {
		t.Fatalf("retry after transient failure got (%d, %q, %v)", c2, id2, err2)
	}
}
