Write table-driven Go tests (`t.Run`) for `registry/manifest_put.go` checking HTTP status codes, the 4 KiB JSON body cap, `pinnedLayers` slice aliasing invariance, and `errors.Is` wrapping:
```go
package registry

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
)

const MaxManifestBytes = 4096

var ErrInvalidDigest = errors.New("layer digest must start with sha256:")

type Manifest struct {
	Repo   string   `json:"repo"`
	Layers []string `json:"layers"`
}

func AcceptManifest(w http.ResponseWriter, r *http.Request, pinnedLayers []string) ([]string, int, error) {
	if r.Method != http.MethodPut {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("got %s: method not allowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxManifestBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var m Manifest
	if err := dec.Decode(&m); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("manifest body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("manifest decode: %w", err)
	}
	for _, d := range m.Layers {
		if !strings.HasPrefix(d, "sha256:") || len(d) != 71 {
			return nil, http.StatusUnprocessableEntity, fmt.Errorf("layer %q: %w", d, ErrInvalidDigest)
		}
	}
	all := make([]string, 0, len(pinnedLayers)+len(m.Layers))
	all = append(all, pinnedLayers...)
	all = append(all, m.Layers...)
	return all, http.StatusCreated, nil
}
