```ts
import { createHash } from 'node:crypto';

export interface CaptureReceipt {
  captureId: string;
  invoiceId: string;
  amountCents: number;
}

export class IdempotentInvoiceFinalizer {
  private ledger = new Map<string, { fingerprint: string; receipt: CaptureReceipt }>();

  constructor(private captureGateway: (invoiceId: string, amountCents: number) => Promise<string>) {}

  async finalize(idemKey: string, invoiceId: string, amountCents: number) {
    const trimmed = idemKey.trim();
    if (trimmed.length < 8) {
      return { status: 400 as const, error: 'short_idempotency_key' };
    }
    const fingerprint = createHash('sha256')
      .update(JSON.stringify([invoiceId, amountCents]))
      .digest('hex');
    const prior = this.ledger.get(trimmed);
    if (prior) {
      if (prior.fingerprint !== fingerprint) {
        return { status: 409 as const, error: 'idempotency_payload_conflict' };
      }
      return { status: 200 as const, receipt: { ...prior.receipt } };
    }
    const captureId = await this.captureGateway(invoiceId, amountCents);
    const receipt: CaptureReceipt = { captureId, invoiceId, amountCents };
    this.ledger.set(trimmed, { fingerprint, receipt });
    return { status: 201 as const, receipt: { ...receipt } };
  }
}
