```go
package dnszone

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
)

const MaxPatchBytes = 1536

var ErrReservedHost = errors.New("cannot modify _acme-challenge via zone patch")

type ZonePatch struct {
	Additions []string `json:"additions"`
}

func ApplyZonePatch(w http.ResponseWriter, r *http.Request, apexRecords []string) ([]string, int, error) {
	if r.Method != http.MethodPatch {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s disallowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxPatchBytes)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var zp ZonePatch
	if err := dec.Decode(&zp); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("patch size: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("patch json: %w", err)
	}
	for _, rec := range zp.Additions {
		if strings.HasPrefix(rec, "_acme-challenge.") {
			return nil, http.StatusConflict, fmt.Errorf("record %q: %w", rec, ErrReservedHost)
		}
	}
	next := make([]string, 0, len(apexRecords)+len(zp.Additions))
	next = append(next, apexRecords...)
	next = append(next, zp.Additions...)
	return next, http.StatusOK, nil
}
