Write a Rust `#[cfg(test)] mod tests` suite for `SplitEscrow` verifying `checked_mul` overflow returning `None`, `FromStr` malformed weight specs, `EscrowStage` invalid state transitions, and inline `[u64; 2]` payout zero-allocation invariants:
```rust
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EscrowStage {
    Funded,
    Locked,
    Settled,
}

#[derive(Debug, PartialEq, Eq)]
pub enum SplitErr {
    BadWeights,
    InvalidStage(EscrowStage, EscrowStage),
    MustBeLocked,
}

pub struct SplitEscrow {
    w_primary: u64,
    w_total: u64,
    stage: EscrowStage,
    legs: [u64; 2],
}

impl FromStr for SplitEscrow {
    type Err = SplitErr;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let (a_str, b_str) = s.split_once('+').ok_or(SplitErr::BadWeights)?;
        let a: u64 = a_str.parse().map_err(|_| SplitErr::BadWeights)?;
        let b: u64 = b_str.parse().map_err(|_| SplitErr::BadWeights)?;
        let total = a.checked_add(b).ok_or(SplitErr::BadWeights)?;
        if total == 0 {
            return Err(SplitErr::BadWeights);
        }
        Ok(Self { w_primary: a, w_total: total, stage: EscrowStage::Funded, legs: [0; 2] })
    }
}

impl SplitEscrow {
    pub fn step(&mut self, next: EscrowStage) -> Result<(), SplitErr> {
        let ok = matches!(
            (self.stage, next),
            (EscrowStage::Funded, EscrowStage::Locked) | (EscrowStage::Locked, EscrowStage::Settled)
        );
        if !ok {
            return Err(SplitErr::InvalidStage(self.stage, next));
        }
        self.stage = next;
        Ok(())
    }

    pub fn compute_legs(&mut self, pot: u64) -> Result<Option<[u64; 2]>, SplitErr> {
        if self.stage != EscrowStage::Locked {
            return Err(SplitErr::MustBeLocked);
        }
        let Some(num) = pot.checked_mul(self.w_primary) else {
            return Ok(None);
        };
        let first = num / self.w_total;
        self.legs = [first, pot - first];
        Ok(Some(self.legs))
    }

    pub fn legs_ptr(&self) -> *const u64 {
        self.legs.as_ptr()
    }
}
