import { z } from 'zod';

const InviteSchema = z.object({
  email: z.string().email(),
  seatTier: z.enum(['member', 'guest']),
}).strict();

const PORTAL_ORIGINS = new Set(['https://portal.team.example']);

export class TeamInviteService {
  private quotas = new Map<string, { sent: number; windowEnd: number }>();

  constructor(private sendMail: (wsId: string, email: string, signal?: AbortSignal) => Promise<void>) {}

  async invite(wsId: string, origin: string | undefined, body: unknown, signal?: AbortSignal) {
    if (!origin || !PORTAL_ORIGINS.has(origin)) {
      return { status: 403 as const, error: 'untrusted_origin' };
    }
    const parsed = InviteSchema.safeParse(body);
    if (!parsed.success) {
      return { status: 400 as const, error: 'invalid_invite' };
    }
    const now = Date.now();
    const q = this.quotas.get(wsId);
    if (!q || now >= q.windowEnd) {
      this.quotas.set(wsId, { sent: 1, windowEnd: now + 90_000 });
    } else if (q.sent >= 3) {
      return { status: 429 as const, error: 'invite_rate_limited' };
    } else {
      q.sent += 1;
    }
    signal?.throwIfAborted();
    await this.sendMail(wsId, parsed.data.email, signal);
    return { status: 202 as const, queued: parsed.data.email };
  }
}
