Write a Vitest round-trip and malformed-frame rejection suite for the RFC 4180 CSV single-row codec `src/csv/rowCodec.ts` below:
```ts
export function encodeCsvRow(cells: string[]): string {
  return cells
    .map((cell) => {
      if (/[",\r\n]/.test(cell)) {
        return `"${cell.replace(/"/g, '""')}"`;
      }
      return cell;
    })
    .join(',');
}

export function decodeCsvRow(line: string): string[] {
  const out: string[] = [];
  let i = 0;
  while (true) {
    if (line[i] === '"') {
      i++;
      let buf = '';
      let closed = false;
      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            buf += '"';
            i += 2;
          } else {
            i++;
            closed = true;
            break;
          }
        } else {
          buf += line[i++];
        }
      }
      if (!closed || (i < line.length && line[i] !== ',')) {
        throw new SyntaxError('malformed quoted csv field');
      }
      out.push(buf);
    } else {
      let buf = '';
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"' || line[i] === '\r' || line[i] === '\n') {
          throw new SyntaxError('unescaped special char in csv field');
        }
        buf += line[i++];
      }
      out.push(buf);
    }
    if (i === line.length) break;
    i++;
  }
  return out;
}
