Write table-driven Go tests (`t.Run`) for `firewall/cidr_sync.go` checking HTTP status codes, the 2 KiB JSON cap, `bootstrapCIDRs` slice non-aliasing, and `errors.Is` wrapping on `0.0.0.0/0` wildcard CIDRs:
```go
package firewall

import (
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/netip"
)

const MaxCIDRBody = 2048

var ErrWildcardCIDR = errors.New("wildcard 0-bit prefix forbidden")

type AllowUpdate struct {
	CIDRs []string `json:"cidrs"`
}

func ParseCIDRAllowlist(w http.ResponseWriter, r *http.Request, bootstrapCIDRs []string) ([]string, int, error) {
	if r.Method != http.MethodPost {
		return nil, http.StatusMethodNotAllowed, fmt.Errorf("method %s disallowed", r.Method)
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxCIDRBody)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var u AllowUpdate
	if err := dec.Decode(&u); err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			return nil, http.StatusRequestEntityTooLarge, fmt.Errorf("cidr body: %w", err)
		}
		return nil, http.StatusBadRequest, fmt.Errorf("cidr decode: %w", err)
	}
	for _, raw := range u.CIDRs {
		pfx, err := netip.ParsePrefix(raw)
		if err != nil {
			return nil, http.StatusBadRequest, fmt.Errorf("parse %q: %w", raw, err)
		}
		if pfx.Bits() == 0 {
			return nil, http.StatusUnprocessableEntity, fmt.Errorf("cidr %q: %w", raw, ErrWildcardCIDR)
		}
	}
	out := make([]string, 0, len(bootstrapCIDRs)+len(u.CIDRs))
	out = append(out, bootstrapCIDRs...)
	out = append(out, u.CIDRs...)
	return out, http.StatusOK, nil
}
