```ts
import { z } from 'zod';

const CreditNoteSchema = z.object({
  cents: z.number().int().min(1).max(50_000),
  memo: z.string().min(4).max(120),
}).strict();

const FINANCE_ORIGINS = new Set(['https://finance.corp.internal']);

export class CreditNoteController {
  private limits = new Map<string, { count: number; resetAt: number }>();

  constructor(private commitLedger: (acctId: string, cents: number, signal?: AbortSignal) => Promise<string>) {}

  async apply(acctId: string, origin: string | undefined, body: unknown, signal?: AbortSignal) {
    if (!origin || !FINANCE_ORIGINS.has(origin)) {
      return { status: 403 as const, error: 'origin_forbidden' };
    }
    const parsed = CreditNoteSchema.safeParse(body);
    if (!parsed.success) {
      return { status: 400 as const, error: 'bad_credit_payload' };
    }
    const now = Date.now();
    const slot = this.limits.get(acctId);
    if (!slot || now >= slot.resetAt) {
      this.limits.set(acctId, { count: 1, resetAt: now + 300_000 });
    } else if (slot.count >= 2) {
      return { status: 429 as const, error: 'credit_rate_limited' };
    } else {
      slot.count += 1;
    }
    signal?.throwIfAborted();
    const noteId = await this.commitLedger(acctId, parsed.data.cents, signal);
    return { status: 201 as const, noteId };
  }
}
