	"reflect"
	"testing"
	"time"
)

func TestApproveRefundRBACMatrix(t *testing.T) {
	now := time.Date(2026, 11, 22, 16, 0, 0, 0, time.UTC)

	cases := []struct {
		name          string
		id            *Identity
		wantStatus    int
		wantCommitted []string
	}{
		{
			name:       "unauthenticated nil identity returns 401",
			id:         nil,
			wantStatus: http.StatusUnauthorized,
		},
		{
			name:       "blank actor id returns 401",
			id:         &Identity{ActorID: "", Merchant: "m_1", Role: "finance_approver", ExpiresAt: now.Add(time.Minute)},
			wantStatus: http.StatusUnauthorized,
		},
		{
			name:       "expired token at exact instant returns 401",
			id:         &Identity{ActorID: "a1", Merchant: "m_1", Role: "finance_approver", ExpiresAt: now},
			wantStatus: http.StatusUnauthorized,
		},
		{
			name:       "wrong_tenant finance_approver returns 403",
			id:         &Identity{ActorID: "a1", Merchant: "m_other", Role: "finance_approver", ExpiresAt: now.Add(time.Minute)},
			wantStatus: http.StatusForbidden,
		},
		{
			name:       "same tenant viewer_role returns 403",
			id:         &Identity{ActorID: "a2", Merchant: "m_1", Role: "viewer", ExpiresAt: now.Add(time.Minute)},
			wantStatus: http.StatusForbidden,
		},
		{
			name:       "same tenant support_l1_role returns 403",
			id:         &Identity{ActorID: "a3", Merchant: "m_1", Role: "support_l1", ExpiresAt: now.Add(time.Minute)},
			wantStatus: http.StatusForbidden,
		},
		{
			name:          "valid same-tenant finance_approver commits once",
			id:            &Identity{ActorID: "a4", Merchant: "m_1", Role: "finance_approver", ExpiresAt: now.Add(time.Second)},
			wantStatus:    http.StatusOK,
			wantCommitted: []string{"rf_77"},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var committed []string
			got := ApproveRefund(tc.id, "m_1", "rf_77", now, func(r string) error {
				committed = append(committed, r)
				return nil
			})
			if got != tc.wantStatus {
				t.Fatalf("status = %d, want %d", got, tc.wantStatus)
			}
			if !reflect.DeepEqual(committed, tc.wantCommitted) {
				t.Fatalf("committed = %v, want %v", committed, tc.wantCommitted)
			}
		})
	}
}
