Write a `pytest` suite for `webhooks/event_sink.py` verifying cached replay on duplicate `Idempotency-Key` deliveries, single downstream dispatch, and `409` conflict rejection when a retried webhook mutates `event_type` or `amount_minor`:
```python
from typing import Callable

class WebhookConflictError(Exception):
    http_status = 409

class WebhookDeduplicator:
    def __init__(self, handler: Callable[[str, int], str]) -> None:
        self._handler = handler
        self._ledger: dict[str, tuple[tuple[str, int], dict]] = {}

    def ingest(self, idem_key: str, event_type: str, amount_minor: int) -> tuple[int, dict]:
        key = idem_key.strip()
        if not key:
            raise ValueError('missing idempotency key')
        sig = (event_type, amount_minor)
        if key in self._ledger:
            orig_sig, saved = self._ledger[key]
            if orig_sig != sig:
                raise WebhookConflictError('mutated webhook body for existing key')
            return 200, dict(saved)
        receipt = self._handler(event_type, amount_minor)
        out = {'receipt': receipt, 'replayed': False}
        self._ledger[key] = (sig, {'receipt': receipt, 'replayed': True})
        return 202, out
```

Write a Rust `#[cfg(test)] mod tests` suite for `send_with_retry` simulating `503` -> `429` (`Retry-After: 4`) -> `200` and verifying that non-idempotent `Verb::Post` without `idem_key` never retries on `NetErr::TimedOut` or `503`:
```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verb {
    Get,
    Post,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UpstreamReply {
    pub status: u16,
    pub retry_after_sec: Option<u64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NetErr {
    TimedOut,
}

pub fn send_with_retry<T, S>(
    verb: Verb,
    idem_key: Option<&str>,
    mut transport: T,
    mut sleep_ms: S,
) -> Result<UpstreamReply, NetErr>
where
    T: FnMut(Option<&str>) -> Result<UpstreamReply, NetErr>,
    S: FnMut(u64),
{
    let retryable = verb == Verb::Get || idem_key.is_some_and(|k| !k.is_empty());
    let max_attempts: u64 = if retryable { 3 } else { 1 };

    for attempt in 1..=max_attempts {
        match transport(idem_key) {
            Ok(rep) if (rep.status < 500 && rep.status != 429) || attempt == max_attempts => {
                return Ok(rep);
            }
            Ok(rep) => {
                let wait = rep.retry_after_sec.filter(|&s| s > 0).map_or(100 * attempt, |s| s * 1_000);
                sleep_ms(wait);
            }
            Err(NetErr::TimedOut) if attempt == max_attempts => return Err(NetErr::TimedOut),
            Err(NetErr::TimedOut) => sleep_ms(100 * attempt),
        }
    }
    unreachable!()
}
