```rust
#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::VecDeque;

    #[test]
    fn keyed_post_retries_503_then_429_respecting_retry_after() {
        let mut scripted = VecDeque::from([
            Ok(UpstreamReply { status: 503, retry_after_sec: None }),
            Ok(UpstreamReply { status: 429, retry_after_sec: Some(4) }),
            Ok(UpstreamReply { status: 200, retry_after_sec: None }),
        ]);
        let mut sleeps = Vec::new();
        let mut seen_keys = Vec::new();

        let out = send_with_retry(
            Verb::Post,
            Some("ik-order-7"),
            |k| {
                seen_keys.push(k.map(str::to_string));
                scripted.pop_front().unwrap()
            },
            |ms| sleeps.push(ms),
        );

        assert_eq!(out, Ok(UpstreamReply { status: 200, retry_after_sec: None }));
        assert_eq!(sleeps, vec![100, 4_000]);
        assert_eq!(seen_keys.len(), 3);
    }

    #[test]
    fn unkeyed_post_never_retries_on_timeout_or_empty_idem_key() {
        for bad_key in [None, Some("")] {
            let mut hits = 0_usize;
            let mut sleeps = Vec::new();
            let res = send_with_retry(
                Verb::Post,
                bad_key,
                |_| {
                    hits += 1;
                    Err(NetErr::TimedOut)
                },
                |ms| sleeps.push(ms),
            );
            assert_eq!(res, Err(NetErr::TimedOut));
            assert_eq!(hits, 1);
            assert!(sleeps.is_empty());
        }
    }

    #[test]
    fn unkeyed_post_returns_503_after_single_attempt() {
        let mut hits = 0_usize;
        let mut sleeps = Vec::new();
        let res = send_with_retry(
            Verb::Post,
            None,
            |_| {
                hits += 1;
                Ok(UpstreamReply { status: 503, retry_after_sec: Some(1) })
            },
            |ms| sleeps.push(ms),
        );
        assert_eq!(res.unwrap().status, 503);
        assert_eq!(hits, 1);
        assert!(sleeps.is_empty());
    }
}
